# ── numbers inside a caption ────────────────────────────────────────────────────────────────────

def test_a_per_share_rate_and_a_bracketed_date_belong_to_the_caption():
    rows = [(li.source_label, li.group_hint, _figures(li)) for li in _build(DIVIDENDS)]
    assert rows == [
        ("Final dividend for the year ended 31 March 2024 of ₹ 3.00 per share (previous year: final"
         " dividend for the year ended 31 March 2023 of ₹ 2.50 per share)",
         "(a) Dividends on equity shares declared and paid during the year",
         {"current": "547.20", "prior": "456.00"}),
        ("Interim dividend for the year ended 31 March 2025 of ₹ 1.50 per share (previous year: nil)",
         "(a) Dividends on equity shares declared and paid during the year", {"current": "273.60"}),
        ("Total dividends paid", "(a) Dividends on equity shares declared and paid during the year",
         {"current": "820.80", "prior": "456.00"}),
        ("Final dividend recommended by the Board of Directors of ₹ 2.00 per share for the year ended"
         " 31 March 2025 (previous year: ₹ 3.00 per share for the year ended 31 March 2024)",
         "(b) Dividends not recognised at the end of the reporting period",
         {"current": "364.80", "prior": "547.20"}),
    ]


def test_a_figure_printed_with_its_currency_in_a_column_is_still_a_figure():
    # "₹" set in the figure column, clear of the caption: not a rate written into the caption.
    label, _ref, values = _scan_row(_words([("Dividend", 0.07, 0.13, 0.5), ("paid", 0.135, 0.17, 0.5),
                                            ("₹", 0.60, 0.61, 0.5), ("3.00", 0.615, 0.65, 0.5)]))
    assert [w.text for w in values] == ["3.00"]


def test_a_date_outside_a_bracket_is_left_to_the_dated_caption_repair():
    label, _ref, values = _scan_row(_words([("Balance", 0.07, 0.12, 0.5), ("as", 0.125, 0.14, 0.5),
                                            ("at", 0.145, 0.155, 0.5), ("31", 0.16, 0.175, 0.5),
                                            ("March", 0.18, 0.22, 0.5), ("2024", 0.225, 0.26, 0.5),
                                            ("486.20", 0.60, 0.65, 0.5)]))
    assert [w.text for w in values] == ["31", "2024", "486.20"]


# ── a caption's own dash ───────────────────────────────────────────────────────────────────────

def test_a_dash_between_caption_words_is_not_a_column():
    row = _words([("(iii)", 0.071, 0.095, 0.56), ("Disputed", 0.099, 0.157, 0.56),
                  ("dues", 0.161, 0.188, 0.56), ("-", 0.192, 0.196, 0.56), ("MSME", 0.200, 0.238, 0.56),
                  ("-", 0.380, 0.385, 0.56), ("-", 0.490, 0.494, 0.56)])
    assert [w.bbox.x0 for w in _matrix_cells(row)] == [0.380, 0.490]


def test_an_ageing_row_keeps_the_caption_after_its_marker():
    rows = [(li.source_label, _figures(li)) for li in _build(AGEING)]
    # The two disputed rows print a dash in every column: they are rows, with no figure.
    assert [cap for cap, _f in rows] == ["(i) MSME", "(ii) Others", "(iii) Disputed dues - MSME",
                                         "(iv) Disputed dues - Others", "Total"]
    assert rows[2][1] == {} and rows[3][1] == {}
    assert rows[0][1] == {"Not due": "2048.90", "Less than 1 year": "135.46", "Total": "2184.36"}


# ── a movement schedule's block headings ────────────────────────────────────────────────────────

def test_a_movement_block_heading_is_the_group_of_its_rows():
    rows = [(li.source_label, li.group_hint) for li in _build(INTANGIBLES)]
    assert rows[:2] == [("Balance as at 1 April 2023", "Gross carrying amount"),
                        ("Additions", "Gross carrying amount")]
    assert ("Balance as at 1 April 2023", "Accumulated amortisation") in rows
    assert not any(cap.startswith(("Gross", "Accumulated")) for cap, _g in rows)


def test_a_wide_movement_schedule_names_every_block():
    rows = [(li.source_label, li.group_hint) for li in _build(PPE)]
    assert rows[0] == ("Balance as at 1 April 2023", "Gross carrying amount")
    assert ("Balance as at 1 April 2023", "Accumulated depreciation") in rows
    assert rows[-2:] == [("As at 31 March 2024", "Net carrying amount"),
                         ("As at 31 March 2025", "Net carrying amount")]


def test_only_a_block_heading_over_a_balance_is_one():
    head = _words([("Gross", 0.07, 0.11, 0.3), ("carrying", 0.12, 0.18, 0.3), ("amount", 0.19, 0.24, 0.3)])
    bal = _words([("Balance", 0.07, 0.12, 0.31), ("as", 0.13, 0.14, 0.31), ("at", 0.15, 0.16, 0.31)])
    other = _words([("of", 0.07, 0.08, 0.31), ("vehicles", 0.09, 0.15, 0.31)])
    assert _heads_a_movement_block(head, bal)
    assert not _heads_a_movement_block(head, other)
    assert not _heads_a_movement_block(bal, bal)


# ── a numbered face heading ─────────────────────────────────────────────────────────────────────

def test_numbered_face_headings_scope_the_rows_under_them():
    items = {li.source_label: li for li in _build(PNL, on_face=True, statement="profit_and_loss")}
    assert "Cost of materials consumed" in items
    assert items["Cost of materials consumed"].section_hint == "IV. Expenses"
    remeasure = items["Remeasurements of the defined benefit plans"]
    assert remeasure.section_hint == "X. Other comprehensive income"
    assert remeasure.group_hint == "A. (i) Items that will not be reclassified to profit or loss"
    assert _figures(remeasure) == {"current": "-42.30", "prior": "18.20"}
    assert (items["(1) Basic (₹)"].section_hint
            == "XII. Earnings per equity share (face value of ₹ 10 each)")
    assert not any(cap.startswith(("IV.", "X.")) for cap in items)


def test_a_flush_continuation_of_a_numbered_caption_is_still_joined():
    head = _words([("XII.", 0.071, 0.095, 0.67), ("Earnings", 0.10, 0.16, 0.67), ("per", 0.18, 0.2, 0.67),
                   ("share", 0.26, 0.3, 0.67), ("(face", 0.31, 0.34, 0.67), ("of", 0.40, 0.41, 0.67),
                   ("₹", 0.42, 0.43, 0.67)])
    tail = _words([("10", 0.071, 0.085, 0.684), ("each)", 0.09, 0.12, 0.684)])
    indented = _words([("(1)", 0.091, 0.11, 0.70), ("Basic", 0.113, 0.15, 0.70)])
    assert not _heads_numbered_face_block(head, tail)          # wraps on, and a bracket is open
    assert not _heads_numbered_face_block(head, indented)   # …and is no heading
    assert _heads_numbered_face_block(_words([("IV.", 0.071, 0.092, 0.19),
                                              ("Expenses", 0.097, 0.171, 0.19)]), indented)


# ── the stand-in's lint ─────────────────────────────────────────────────────────────────────────

def _standin():
    path = Path(__file__).resolve().parents[1] / "scripts" / "llm_standin.py"
    spec = importlib.util.spec_from_file_location("llm_standin_captions", path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = mod
    spec.loader.exec_module(mod)
    return mod


def test_the_lint_reads_a_long_printed_caption_as_a_caption():
    lint = _standin()
    assert lint.is_fragment("Estimated amount of contracts remaining to be executed on capital account"
                            " and not provided for (net of capital advances)") is None
    assert lint.is_fragment("X. Other comprehensive income A. (i) Items that will not be reclassified"
                            " to profit or loss Remeasurements of the defined benefit plans")
    assert lint.is_fragment("Final dividend recommended by the Board of Directors of ₹ 2.00 per share"
                            " for the year ended 31 March 2025 (previous year: ₹ 3.00 per share for"
                            " the year ended")


def test_the_lint_flags_a_caption_that_repeats_its_group():
    lint = _standin()
    assert lint.heads_its_own_caption("Gross carrying amount Balance as at 1 April 2023",
                                      "Gross carrying amount")
    assert lint.heads_its_own_caption("Current tax on profits for the year", "Current tax:") is None
    assert lint.heads_its_own_caption("Balance as at 1 April 2023", "Gross carrying amount") is None
